//! 🤝️ Actual whole owned ABI startup admits its borrowed channel and returns every physical and VM receipt.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::RetainedCloneGrant;
fn clock()->Option<u64>{Some(1000)}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
fn observed<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn core_bytes(component:&[u8])->&[u8]{assert_eq!(component[8],1);let mut pc=9;let mut length=0;let mut shift=0;loop{let byte=component[pc];pc+=1;length|=usize::from(byte&127)<<shift;shift+=7;if byte&128==0{break}}&component[pc..pc+length]}
/// 🌱️ Whole current ABI assets use original paid startup; channel output is read from its actual memory rather than a fresh output Vec.
#[test]
fn original_owned_startup_admits_borrowed_channel_with_measured_vm_and_paid_final_close(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert_eq!(fixture["channelVersion"].as_u64().unwrap(),u64::from(semio_framework_os_kernel::CHANNEL_VERSION));let bytes=super::super::owned_runtime_tests::owned_channel_guest(semio_framework_os_kernel::CHANNEL_VERSION);let engine=wasmtime::Engine::default();let module=wasmtime::Module::new(&engine,core_bytes(&bytes)).unwrap();let mut store=wasmtime::Store::new(&engine,());let oracle=wasmtime::Instance::new(&mut store,&module,&[]).unwrap();let packed=oracle.get_typed_func::<(),i64>(&mut store,OwnedSemioExport::ChannelVersion.core_name()).unwrap().call(&mut store,()).unwrap()as u64;let memory=oracle.get_memory(&mut store,"memory").unwrap().data(&store);let pointer=packed as u32 as usize;let version: u32=serde_json::from_slice(&memory[pointer..pointer+(packed>>32)as usize]).unwrap();assert_eq!(version,semio_framework_os_kernel::CHANNEL_VERSION);
 let runtime=OwnedRuntime::new(clock);let compiled=runtime.compile_component(&bytes).unwrap();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let(owner,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_actor_startup(&compiled,cx)}).unwrap());assert_eq!(heap,(0,0));let mut owner=owner.unwrap();let mut born=0;let mut released=0;let mut execution=0;let mut turns=0;
 while !owner.ready(){epoch+=1;let(call,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:1024,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;let original_input=semio_framework_actor::RetainedTurnInput::borrow_original(cx)?;let budget=owner.requires_execution().then(||OriginalGuestExecutionBudget{input:original_input,fuel:1,deadline_us:cx.deadline_us()});owner.advance_step(&compiled,cx,budget)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;if let Some(receipt)=call.execution{assert_eq!(receipt.spent_fuel,Some(1));execution+=receipt.spent_fuel.unwrap();}assert!(matches!(call.result.unwrap(),OwnedActorStartupStatus::Pending|OwnedActorStartupStatus::Ready));turns+=1;assert!(turns<150)}assert_eq!(execution,fixture["expectedInstructions"].as_u64().unwrap());assert_eq!(owner.observed_channel(),Some(version));let pointer=owner.original_resources().unwrap().memory(0).unwrap().as_ptr();assert!(!pointer.is_null());caller.cancel().cancel_now();for _ in 0..80{if owner.terminal_is_empty(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&compiled,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual Owned phased startup wholeABI={} borrowedChannel={version} WasmtimeAndSerde=true turns={turns} measuredVM={execution} physicalBirth={born} paidRelease={released} cancelledOriginalClose=true",OwnedSemioExport::ALL.len());
}

/// 📤️ Actual final storage keeps the same Core address and original source through copy denial, foreign refusal and paid terminal close.
#[test]
fn original_owned_startup_final_transfer_preserves_same_core_and_paid_source(){
 let bytes=super::super::owned_runtime_tests::owned_channel_guest(semio_framework_os_kernel::CHANNEL_VERSION);let runtime=OwnedRuntime::new(clock);let compiled=runtime.compile_component(&bytes).unwrap();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_actor_startup(&compiled,cx)}).unwrap();let mut born=0;let mut released=0;for _ in 0..150{if owner.as_ref().unwrap().ready(){break}epoch+=1;let(_,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:1024,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;let owner=owner.as_mut().unwrap();let original_input=semio_framework_actor::RetainedTurnInput::borrow_original(cx)?;let execution=owner.requires_execution().then(||OriginalGuestExecutionBudget{input:original_input,fuel:1,deadline_us:cx.deadline_us()});let call=owner.advance_step(&compiled,cx,execution)?;call.result?;Ok(())}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}assert!(owner.as_ref().unwrap().ready());let original_pointer=owner.as_ref().unwrap().original_resources().unwrap().memory(0).unwrap().as_ptr();epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_actor_startup_step(&mut owner,&compiled,semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,cx)}).unwrap().is_none());assert!(owner.as_ref().unwrap().final_source.is_some());epoch+=1;let(taken,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_actor_startup_step(&mut owner,&compiled,semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,cx)}).unwrap());assert!(taken.is_none());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert_eq!(owner.as_ref().unwrap().original_resources().unwrap().memory(0).unwrap().as_ptr(),original_pointer);epoch+=1;let(taken,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:4096,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;runtime.take_actor_startup_step(&mut owner,&compiled,semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,cx)}).unwrap());assert_eq!(heap,(0,0));let mut instance=Some(taken.unwrap());assert!(owner.is_none());assert_eq!(caller.receipt().copied_bytes,size_of::<OwnedGuestInstance>());assert_eq!(instance.as_ref().unwrap().original_startup_input().unwrap().epoch,epoch);assert_eq!(instance.as_mut().unwrap().original_core_mut().unwrap().1.resources().unwrap().memory(0).unwrap().as_ptr(),original_pointer);assert!(instance.as_ref().unwrap().actor.is_none());let mut foreign=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let(result,heap)=observed(||foreign.turn(stock,|cx|{cx.bind_original_source_epoch(epoch+1)?;runtime.close_original_actor_step(&mut instance,&compiled,cx)}));assert!(result.is_err());assert_eq!(heap,(0,0));assert!(instance.is_some());foreign.retire(stock);caller.cancel().cancel_now();for _ in 0..100{if instance.is_none(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_actor_step(&mut instance,&compiled,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(instance.is_none());assert_eq!(born,released);caller.retire(stock);eprintln!("[DEBUG] actual Owned final storage headerBytes={} deniedCopy0=true paid4096=true sameOriginalCoreAddress=true sourceHeldUntilFinalSlotDrop=true foreignSameBusinessRootRefused=true physicalBirth={born} paidRelease={released}",size_of::<OwnedGuestInstance>());
}
